INSERT INTO public.products (product_id, name, brand, description, price, sizes, image_url, stock_quantity, category, colors_general) VALUES
('KVP026', 'Baskets Adidas Femme Gazelle Indoor Core Black', ' Adidas', 'Découvrez l''élégance intemporelle associée au confort moderne avec ces baskets signées Adidas. Inspirées par l''héritage sportif de la marque, elles affichent une allure rétro irrésistible, rehaussée par un dessus en suède doux et luxueux. Les célèbres 3-Stripes et un talon contrastant offrent une touche emblématique immédiatement reconnaissable, idéales pour les passionnés de mode qui recherchent l''authenticité. La doublure synthétique assure un port agréable tout au long de la journée, tandis que la fermeture à lacets garantit un ajustement parfait. La semelle extérieure en gomme, robuste et adhérente, confère non seulement une excellente traction mais accentue également le style vintage de la chaussure. Initialement conçues comme chaussures d''entraînement, ces baskets s''intègrent désormais parfaitement à toutes les tenues urbaines. Elles représentent un choix incontournable pour toutes celles qui apprécient la qualité, la durabilité et le raffinement. Offrez-vous une pièce maîtresse qui sublimera votre collection et affirmez votre style avec assurance grâce au savoir-faire inégalé d''Adidas.', '120', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_gazelle_indoor_core_black_cream_white_gum_8.jpg', '4', 'Femme', '[''noir'', ''blanc'']'),
('KVP027', 'Baskets Adidas Femme Adidas BRMD Wonder Mauve', ' Adidas', 'Découvrez une paire de baskets qui incarne parfaitement l''alliance entre l''héritage et la modernité. Inspirée par une silhouette emblématique des années 80, cette création de la marque Adidas séduit par sa matière en suède haut de gamme et ses couleurs uniques : Wonder Mauve, Almost Yellow et Wonder Quartz. Les célèbres 3-Stripes contrastantes ajoutent une touche rétro instantanément reconnaissable, tandis que la large fermeture à lacets et la collerette rembourrée offrent un confort optimal et une allure contemporaine. La doublure synthétique assure une sensation agréable à chaque pas, et la semelle extérieure en caoutchouc gomme garantit adhérence et durabilité, même lors d''un usage quotidien. Convient aux femmes à la recherche d''une basket aussi élégante que pratique, ce modèle est idéal pour celles qui souhaitent affirmer leur style tout en profitant du savoir-faire et du confort inégalés d''Adidas. Parfait pour compléter toutes vos tenues, il apporte une note sportive et raffinée à votre garde-robe. Adoptez l''excellence d''une marque légendaire et laissez-vous séduire par un design intemporel revisité pour la femme moderne.', '110', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "36", "38", "40"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_adidas_brmd_wonder_mauve_almost_yellow_wonder_quartz_8.jpg', '6', 'Femme', '[''jaune'']'),
('KVP028', 'Baskets Adidas Femme Samba Jane Cream White', ' Adidas', 'Découvrez une paire de baskets qui incarne l''alliance parfaite entre héritage sportif et élégance contemporaine. Signée par la marque Adidas, cette création pour femmes se distingue par son dessus en cuir raffiné, offrant une allure sophistiquée et une résistance optimale au quotidien. Inspirée de l''iconique modèle Samba, elle revisite la silhouette classique avec une esthétique Mary Jane moderne, idéale pour celles qui recherchent une touche d''originalité dans leur garde-robe. La fermeture à scratch réglable garantit un ajustement personnalisé et pratique, tandis que la doublure synthétique procure un confort exceptionnel à chaque pas. Les célèbres 3-Stripes dentelées et l''inscription dorée subtile sur le côté témoignent du savoir-faire et de l''attention portée aux détails propres à Adidas. La semelle extérieure en caoutchouc gomme assure une adhérence remarquable, adaptée à toutes les surfaces. Avec sa combinaison de couleurs élégantes – crème, gomme et noir – cette basket s''impose comme un choix incontournable pour sublimer aussi bien des tenues décontractées que plus habillées. Optez pour une pièce tendance et intemporelle qui met en valeur votre style tout en garantissant confort et performance.', '90', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "36", "38", "40"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_samba_jane_cream_white_gum_core_black_8.jpg', '18', 'Femme', '[''noir'', ''blanc'']'),
('KVP029', 'Baskets Adidas Femmes Handball Spezial Glow Blue', ' Adidas', 'Découvrez un modèle emblématique qui incarne parfaitement l''alliance entre héritage sportif et tendances actuelles. Inspirées du style rétro des années 70, ces baskets pour femmes séduisent par leur design authentique et leur confort moderne. La matière principale, un cuir de qualité rehaussé de détails en suède premium, offre une allure élégante et une grande durabilité au quotidien. La couleur vibrante, mêlant bleu éclatant et rouge, attire tous les regards et s''associe aisément à de nombreuses tenues, pour une touche sportive et sophistiquée. Les fameuses 3-Stripes sur le côté, signature de la marque Adidas, ainsi que l''inscription en doré, soulignent le caractère exclusif de cette paire. La doublure synthétique assure un confort optimal, tandis que la semelle extérieure en caoutchouc garantit une excellente adhérence sur toutes les surfaces. Grâce à la fermeture à lacets, chaque pied bénéficie d''un ajustement parfait. Conviennent aux femmes à la recherche d''un modèle unique, alliant style vintage et innovation, ces baskets sont un choix incontournable pour celles qui souhaitent afficher une allure intemporelle tout en profitant du savoir-faire et de la qualité reconnue d''Adidas.', '110', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_handball_spezial_glow_blue_red_blue_spark_8.jpg', '5', 'Femme', '[''rouge'', ''bleu'']'),
('KVP030', 'Baskets Adidas Femme Handball Spezial Orange Tint', ' Adidas', 'Découvrez une paire de baskets qui allie parfaitement l''héritage du style rétro et l''innovation moderne. Imaginée pour offrir une expérience unique, cette création emblématique séduit par son design inspiré des années 70 et son élégante combinaison de couleurs Orange Tint, Powder Plum et Gum. Son dessus en cuir haut de gamme garantit une grande durabilité et un confort optimal, tandis que la doublure synthétique assure une sensation agréable à chaque pas. La semelle extérieure en caoutchouc robuste offre une adhérence fiable, idéale pour un usage quotidien. Les célèbres 3 bandes et l''inscription dorée sur le côté soulignent l''authenticité et le prestige de la marque Adidas. Conçue à l''origine pour la performance sportive, cette basket s''impose aujourd''hui comme un incontournable de la mode urbaine, parfaite pour les femmes en quête d''un look unique, d''une qualité supérieure et d''un clin d''œil à l''histoire du sport. Optez pour une chaussure qui ne fait aucun compromis entre style, confort et tradition.', '110', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40", "42"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_handball_spezial_orange_tint_powder_plum_gum_8.jpg', '17', 'Femme', '[''orange'', ''noir'']'),
('KVP031', 'Baskets Adidas Unisexe Handball Spezial Maroon', ' Adidas', 'Découvrez l''alliance parfaite entre héritage sportif et style contemporain avec ces baskets emblématiques signées Adidas. Conçues à l''origine pour la pratique du handball en 1979, elles se sont imposées au fil des années comme une référence incontournable du streetwear. Leur dessus en cuir de qualité supérieure, décliné dans des tons marron et preloved red, apporte une touche d''élégance et de sophistication à chaque tenue. Les détails raffinés tels que les 3-Stripes cousues à la main et l''inscription dorée « Spezial » sur le côté témoignent du savoir-faire unique de la marque. La doublure textile assure un confort optimal, tandis que la semelle extérieure en caoutchouc garantit une adhérence durable, idéale aussi bien pour la ville que pour les activités sportives. Grâce à leur fermeture à lacets, ces baskets offrent un ajustement parfait et conviennent aussi bien aux hommes qu''aux femmes. Opter pour ce modèle, c''est choisir la qualité, l''authenticité et le confort légendaires d''Adidas, une marque reconnue mondialement pour son design innovant et son engagement envers la performance. Ces baskets sont le choix idéal pour tous ceux qui recherchent une pièce polyvalente, à la fois tendance et intemporelle, à ajouter à leur collection.', '110', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "42 2/3", "43 1/3", "44 2/3", "45 1/3", "46 2/3"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_unisex_handball_spezial_maroon_preloved_red_gum_8.jpg', '5', 'Unisexe', '[''rouge'', ''noir'']'),
('KVP032', 'Baskets Adidas Homme Gazelle Alumina', ' Adidas', 'Découvrez l''alliance parfaite entre le style intemporel et l''innovation contemporaine avec ces baskets signées par la marque Adidas. Conçues pour les hommes exigeants, elles se distinguent par une élégante combinaison de couleurs Alumina, Blue et Gum. Leur matière supérieure en cuir et synthétique offre une allure sophistiquée tout en garantissant une grande durabilité. La doublure synthétique et textile assure une excellente respirabilité, idéale pour un confort au quotidien. La semelle extérieure en caoutchouc procure une adhérence fiable sur toutes les surfaces, rendant ces baskets adaptées à toutes les occasions. Les détails iconiques, tels que les 3-Stripes dentelées sur le côté, le logo Trefoil sur la languette et le talon, ainsi que le marquage doré sur le côté, soulignent le caractère authentique de ce modèle. La fermeture à lacets permet un ajustement parfait à chaque morphologie de pied. Parfaites pour sublimer n''importe quelle tenue, ces baskets incarnent l''excellence et le savoir-faire d''Adidas, une marque reconnue mondialement pour la qualité et le confort de ses chaussures. Offrez-vous une paire qui traverse les tendances et reste un choix incontournable pour tous les amateurs de mode et de performance. Convient pour : les hommes.', '110', '["40 2/3", "41 1/3", "42 2/3", "43 1/3", "44 2/3", "45 1/3", "46 2/3", "40", "42", "44", "46"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_men_gazelle_alumina_blue_gum_8.jpg', '16', 'Homme', '[''noir'', ''bleu'']'),
('KVP033', 'Baskets Adidas Enfant Superstar II Core Black', ' Adidas', 'Découvrez l''alliance parfaite entre le style intemporel et le confort moderne avec ces baskets pour enfants signées Adidas. Conçues pour accompagner les plus jeunes dans toutes leurs aventures, ces chaussures se distinguent par leur design iconique, reconnaissable aux célèbres trois bandes dentelées et à l''emblématique coque en caoutchouc à l''avant, offrant une protection optimale au quotidien. Fabriquées à partir de matières synthétiques et de cuir enduit, elles garantissent une grande durabilité tout en restant faciles à entretenir avec un simple chiffon humide et un détergent doux. La doublure textile intérieure et la semelle intérieure préformée assurent un confort durable, tandis que la languette et le talon rembourrés procurent un maintien agréable. La semelle extérieure en caoutchouc, dotée d''un motif à chevrons, offre une adhérence exceptionnelle sur toutes les surfaces, idéale pour les enfants actifs. Grâce à leur fermeture à lacets, ces baskets s''ajustent parfaitement à chaque pied. Leur couleur noire et blanche s''harmonise facilement avec toutes les tenues, rendant ces chaussures polyvalentes pour l''école, les loisirs ou les sorties. Optez pour un modèle emblématique de la marque Adidas, synonyme de qualité, de style et de performance, et offrez à votre enfant le meilleur du confort et de la mode. Convient aux enfants.', '70', '["30,5", "28", "28,5", "29", "30", "31", "31,5", "32"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_kids_superstar_ii_core_black_cloud_white_core_black_8.jpg', '26', 'Enfant', '[''noir'', ''blanc'']'),
('KVP034', 'Baskets Adidas Femme Sambae Cloud White', ' Adidas', 'Découvrez une paire de baskets qui allie parfaitement l''héritage sportif et l''élégance contemporaine. Inspirée des chaussures d''entraînement de football classiques, cette création signée Adidas séduit par son design rétro rehaussé de détails modernes. Son dessus en cuir, orné d''un délicat motif floral et des iconiques 3-Stripes crantées, offre une allure raffinée et originale. La plateforme en gomme, associée à une semelle extérieure robuste, assure non seulement une touche de hauteur supplémentaire, mais aussi une excellente adhérence et une grande durabilité au quotidien. La doublure synthétique et la fermeture à lacets garantissent un confort optimal ainsi qu''un ajustement parfait, répondant aux exigences des femmes actives et soucieuses de leur style. Avec sa palette de couleurs nuancées – Cloud White, Linen Green et Gum – cette basket s''adapte aisément à toutes vos tenues, qu''elles soient sportives ou décontractées. Depuis plus de 70 ans, Adidas est reconnue pour la qualité et le confort de ses chaussures, faisant de ce modèle un incontournable pour celles qui recherchent une basket polyvalente, tendance et intemporelle. Offrez-vous une expérience unique où mode et performance ne font qu''un.', '120', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40", "42"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_sambae_cloud_white_linen_green_gum_10.jpg', '26', 'Femme', '[''vert'', ''noir'', ''blanc'']'),
('KVP035', 'Baskets Adidas Femme Gazelle Bold Wonder Mauve', ' Adidas', 'Découvrez l''alliance parfaite entre style rétro et modernité avec ces baskets signées Adidas. Dotées d''une tige en suède doux dans une teinte Wonder Mauve raffinée, elles sont sublimées par les emblématiques 3-Stripes et un talon Off White, offrant une touche élégante et intemporelle à votre tenue. La plateforme en gomme, composée de trois couches, confère non seulement une hauteur supplémentaire, mais apporte également une allure vintage très recherchée. La doublure synthétique assure un confort optimal tout au long de la journée, tandis que le détail sophistiqué du lacet bijou sur la languette du talon et le logo distinctif sur la languette soulignent l''authenticité du modèle. Polyvalentes, ces baskets s''associent aisément à une grande variété de looks décontractés, faisant d''elles un choix incontournable pour celles qui souhaitent allier tendance et praticité. Offrez-vous une pièce unique, parfaite pour rehausser votre garde-robe et affirmer votre style avec l''excellence et le savoir-faire de la marque Adidas.', '120', '["35 1/3", "36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40", "42"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_gazelle_bold_wonder_mauve_off_white_gum_10.jpg', '0', 'Femme', '[''noir'', ''blanc'']');